'use strict';
const token=document.querySelector('meta[name="app-token"]').content;
let state=null,page='Forside',selected='',area='',status='Alle',query='',view='Liste',loanTab='Aktive',year=serviceYear(new Date().toISOString().slice(0,10)),reportTab='Rapport';
let deskTab='Udlever',cardTab='Kort';
let addressTab='Mangler på kort',addressPostcode='',addressPage=0;
let mapImage='',mapDraft=[],mapCard='',editMap=false,saveQueue=Promise.resolve(),autosaveTimer=null,toastTimer=null;
const addressTypes=['Hus','Lejlighed','Lejlighedskompleks','Butik','Kontor','Virksomhed','Andet'];
const el=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>s?new Date(s+'T12:00:00').toLocaleDateString('da-DK'):'—';
const cmp=(a,b)=>String(a).localeCompare(String(b),'da',{numeric:true});
const dayDiff=(a,b)=>Math.floor((Date.parse(a+'T12:00:00Z')-Date.parse(b+'T12:00:00Z'))/86400000);
function serviceYear(day){return Number(day.slice(0,4))+(day.slice(5)>='09-01'?1:0);}
const yearLabel=y=>`${y-1}/${y}`;
const card=id=>state.cards.find(c=>c.id===id);
const current=()=>card(selected);
const areaName=id=>state.areas.find(a=>a.id===id)?.name||'Intet område';
const publisherName=id=>state.publishers.find(p=>p.id===id)?.name||'Ukendt';
const loanFor=id=>state.loans.find(l=>l.card_id===id&&!l.returned);
const visitsCount=c=>(c.addresses||[]).reduce((n,a)=>n+a.count,0);
const position=c=>loanFor(c.id)?'Udleverede distriktskort':c.in_folder?'Kort i mappen':'Kort i kassen';
const age=c=>c.last_completed?dayDiff(state.today,c.last_completed):Infinity;
function fourMonths(day){let d=new Date(day+'T12:00:00'),n=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+4);let max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(n,max));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function saved(message='Alle ændringer er gemt'){el('saveState').textContent=message;el('saveState').className='';}
function saving(){el('saveState').textContent='Gemmer…';el('saveState').className='';}
function failed(message){el('saveState').textContent='Ikke gemt · '+message;el('saveState').className='error';}
function toast(message){el('toast').textContent=message;el('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').style.display='none',4500);}
async function api(path,body){
 if(path==='/api/mutate'&&state?.revision)body={...body,data:{...body.data,_revision:state.revision}};
 let r;try{r=await fetch(path,{method:body?'POST':'GET',headers:{'X-Distrikt-Token':token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});}
 catch(error){failed(body?'Gemning ikke bekræftet · forbindelsen er afbrudt. Kontrollér før du prøver igen.':'Ingen forbindelse · kontrollér Wi-Fi / VPN.');throw Error(body?'Forbindelsen blev afbrudt. Ændringen kan være nået frem; genindlæs data og kontrollér før du prøver igen.':'Ingen forbindelse til appen. Kontrollér Wi-Fi / VPN.');}
 if(!r.ok){let data=await r.json().catch(()=>({error:'Ingen forbindelse til den lokale app.'}));if(r.status===401)failed('Login er udløbet · log ind igen.');throw Error(data.error);}
 if(path==='/api/mutate'){const payload=await r.clone().json();if(payload.revision&&state)state.revision=payload.revision;}
 return r;
}
async function refresh(){state=await(await api('/api/state')).json();if(!selected&&state.cards.length)selected=state.cards[0].id;render();}
function mutate(action,data,{close=true,message='Gemt',autosave=false}={}){saving();const work=saveQueue.then(async()=>{await api('/api/mutate',{action,data});if(action.startsWith('geo.')||action.startsWith('ignore.')||action.startsWith('address.change.')||action.startsWith('card.restructure.')||['delete','restore','recovery.purge','workflow.undo'].includes(action))await GeoUI.load();await refresh();saved();if(close)closeDialog();const error=el('formError');if(error)error.textContent='';if(!autosave)toast(message);const note=el('formSaved');if(note)note.textContent='Gemt automatisk';});saveQueue=work.catch(()=>{});return work.catch(e=>{failed(e.message);const err=el('formError');if(err)err.textContent=e.message;else toast(e.message);throw e;});}
function openDialog(html){frontResizeObserver?.disconnect();DistrictMap.dispose();clearTimeout(autosaveTimer);el('dialog').innerHTML='<button type="button" class="dialogClose" data-action="close" aria-label="Luk" title="Luk">×</button>'+html;el('dialog').showModal();el('dialog').scrollTop=0;}
function closeDialog(){frontResizeObserver?.disconnect();DistrictMap.dispose();clearTimeout(autosaveTimer);el('dialog').close();}
function empty(message){return `<div class="empty">${message}</div>`;}
function searchText(c){return [c.number,c.name,areaName(c.area_id),c.kind,...(c.addresses||[]).flatMap(a=>[a.road,a.numbers,a.type])].join(' ').toLowerCase();}
function matches(c){return (!query||searchText(c).includes(query.toLowerCase()))&&(!area||c.area_id===area);}
function table(cards,selectable=false){if(selectable)AdminUI.visible=cards.map(c=>c.id);return `<div class="tablewrap"><table><thead><tr>${selectable?'<th>Vælg</th>':''}<th>Kort</th><th>Område</th><th>Senest gennemgået</th><th>Status</th><th></th></tr></thead><tbody>${cards.map(c=>`<tr class="cardRow ${c.id===selected?'selected':''}" data-card-row="${esc(c.id)}" tabindex="0" aria-label="Vælg kort ${esc(c.number)}" aria-selected="${c.id===selected}">${selectable?`<td><input type="checkbox" data-bulk-id="${esc(c.id)}" aria-label="Vælg kort ${esc(c.number)}" ${AdminUI.selected.has(c.id)?'checked':''}></td>`:''}<td><button class="link" data-action="select" data-id="${c.id}"><b>${esc(c.number)}</b>${c.name?' · '+esc(c.name):''}</button><small>${c.temporary?'Midlertidigt kort · kun register':visitsCount(c)+' besøg'}</small></td><td>${esc(areaName(c.area_id))}<small>${esc(c.kind)}</small></td><td>${fmt(c.last_completed)}${!c.last_completed?'<small>Ikke oplyst</small>':''}</td><td><span class="badge">${position(c)}</span>${c.front_revision||c.back_revision?'<small>Ændret '+(c.front_revision?'forside':'')+(c.front_revision&&c.back_revision?' og ':'')+(c.back_revision?'bagside':'')+'</small>':''}</td><td><button data-action="detail" data-id="${c.id}">Åbn</button> <button data-action="show-map" data-id="${c.id}">Se på kort</button></td></tr>`).join('')||`<tr><td colspan="${selectable?6:5}">Ingen kort fundet.</td></tr>`}</tbody></table></div>`;}
function controls(extra=''){return `<div class="toolbar"><input id="search" aria-label="Søg kort" placeholder="Søg nummer, navn, vej eller adressetype" value="${esc(query)}"><select id="areaFilter" aria-label="Område"><option value="">Alle områder</option>${state.areas.slice().sort((a,b)=>cmp(a.name,b.name)).map(a=>`<option value="${a.id}" ${area===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>${extra}</div>`;}
function details(c){if(!c)return `<section class="panel">${empty('Vælg et kort for at udlevere eller se oplysninger.')}</section>`;let l=loanFor(c.id),blocked=state.settings.require_revision&&(c.front_revision||c.back_revision);return `<section class="panel details"><span class="badge">${position(c)}</span><strong>Kort ${esc(c.number)}</strong><p>${esc(c.name)}<br><small>${esc(areaName(c.area_id))} · ${esc(c.kind)}</small></p><div class="line"><span>Senest gennemgået</span><b>${fmt(c.last_completed)}</b></div><div class="line"><span>Besøg</span><b>${c.temporary?'Ikke indtastet':visitsCount(c)}</b></div>${l?`<div class="line"><span>Udleveret til</span><b>${esc(publisherName(l.publisher_id))}</b></div>`:''}<div class="actions">${l?`<button class="primary" data-action="return" data-id="${l.id}">Aflever til kassen</button><button data-action="complete" data-id="${l.id}">Gennemgået · behold kort</button>`:`<button class="primary" data-action="issue" data-id="${c.id}" ${blocked?'disabled':''}>${c.in_folder?'Udlever kort':'Registrer eksisterende udlån'}</button><button data-action="folder" data-id="${c.id}">${c.in_folder?'Flyt til kassen':'Læg i mappen'}</button>`}<button data-action="detail" data-id="${c.id}">Fremvis kort</button><button data-action="show-map" data-id="${c.id}">Se på kort</button></div>${l&&c.back_revision?'<p class="notice warning">Det udleverede fysiske kort skal have ajourført IB-bagsiden.</p>':''}${blocked?'<p class="hint">En ændret side skal godkendes efter print.</p>':''}</section>`;}
function folderPlan(){const cfg=state.settings,min=cfg.folder_minimum,eligible=c=>!loanFor(c.id)&&!(cfg.require_revision&&(c.front_revision||c.back_revision)),inside=state.cards.filter(c=>c.in_folder&&eligible(c)),available=state.cards.filter(c=>!c.in_folder&&eligible(c)).sort((a,b)=>age(b)-age(a)||cmp(a.number,b.number)),typed=state.cards.filter(c=>c.kind!=='Ukendt'),rural=cfg.rural_mode==='manual'?cfg.rural_minimum:typed.length?Math.round(min*typed.filter(c=>c.kind==='Land').length/typed.length):0,urban=min-rural,need=Math.max(0,min-inside.length),picked=[],pick=(predicate,n)=>{for(const c of available.filter(predicate)){if(n<=0)break;if(!picked.includes(c)){picked.push(c);n--;}}};pick(c=>c.kind==='Land',Math.min(need,Math.max(0,rural-inside.filter(c=>c.kind==='Land').length)));pick(c=>c.kind==='By',Math.min(need-picked.length,Math.max(0,urban-inside.filter(c=>c.kind==='By').length)));pick(()=>true,need-picked.length);return {need,picked,inside,rural,urban,typed:typed.length,shortfall:Math.max(0,need-picked.length)};}
function deskReturns(){const q=query.toLowerCase(),loans=state.loans.filter(l=>!l.returned).filter(l=>[card(l.card_id)?.number,publisherName(l.publisher_id),areaName(card(l.card_id)?.area_id)].join(' ').toLowerCase().includes(q)).sort((a,b)=>cmp(card(a.card_id)?.number,card(b.card_id)?.number));return `<section class="panel"><div class="tablewrap"><table><thead><tr><th>Kort</th><th>Forkynder</th><th>Udleveret</th><th></th></tr></thead><tbody>${loans.map(l=>`<tr><td><button class="link" data-action="detail" data-id="${l.card_id}">Kort ${esc(card(l.card_id)?.number)}</button></td><td>${esc(publisherName(l.publisher_id))}</td><td>${fmt(l.assigned)}</td><td><button class="primary" data-action="return" data-id="${l.id}">Aflever til kassen</button></td></tr>`).join('')||'<tr><td colspan="4">Ingen udleverede kort fundet.</td></tr>'}</tbody></table></div></section>`;}
function home(){
 const p=folderPlan(),ds=state.cards.filter(c=>c.in_folder&&!loanFor(c.id)&&matches(c)).sort((a,b)=>age(b)-age(a)||cmp(a.number,b.number));
 if(!ds.some(c=>c.id===selected)&&ds.length)selected=ds[0].id;
 if(!state.cards.length)return `<section class="panel welcome"><h2>Begynd med dine kortnumre</h2><p>Et kortnummer er nok. Vejlisten og korttegningen kan du tilføje senere på samme kort.</p><button class="primary" data-action="new-card">Tilføj første kortnummer</button> <button data-admin="quick">Opret flere kortnumre</button><p class="hint">Opret derefter forkynderne og registrer de kort, der allerede er udleveret.</p><div class="actions"><button data-action="go" data-page="Forkyndere">Forkyndere</button><button data-action="initial-loan">Registrer eksisterende udlevering</button></div></section>`;
 const counts=[['Kort i mappen',state.cards.filter(c=>c.in_folder&&!loanFor(c.id)).length,'Kort i mappen'],['Udleverede distriktskort',state.loans.filter(l=>!l.returned).length,'Udleverede distriktskort'],['Kort i kassen',state.cards.filter(c=>!c.in_folder&&!loanFor(c.id)).length,'Kort i kassen']];
 return `<div class="deskCounts">${counts.map(([name,count,filter])=>`<button data-action="stock" data-status="${filter}"><strong>${count}</strong><span>${name}</span></button>`).join('')}</div><div class="tabs deskTabs">${['Udlever','Aflever'].map(t=>`<button data-action="desk-tab" data-tab="${t}" class="${deskTab===t?'active':''}">${t==='Udlever'?'Udlever fra mappen':'Aflever til kassen'}</button>`).join('')}</div>${deskTab==='Aflever'?`<div class="toolbar"><input id="search" aria-label="Søg udleveret kort" placeholder="Søg kortnummer eller forkynder" value="${esc(query)}"></div>${deskReturns()}`:`${controls()}<div class="workspace"><section class="panel"><div class="between"><h2>Kort i mappen</h2><small>${ds.length} ledige kort</small></div>${ds.length?table(ds):empty('Ingen ledige kort matcher. Fyld mappen fra kassen nedenfor.')}</section>${details(ds.find(c=>c.id===selected))}</div>`}<section class="panel folderSummary"><div class="between"><div><h2><b>${p.need}</b> kort skal i mappen</h2><p class="hint">Minimum ${state.settings.folder_minimum}${p.typed||state.settings.rural_mode==='manual'?` · ca. ${p.urban} by / ${p.rural} land`:''}</p></div><button data-action="new-card">Tilføj kortnummer</button></div>${p.need?`<details ${p.picked.length?'open':''}><summary>Se forslag fra kassen</summary><div class="picks">${p.picked.map(c=>`<span>Nr. <b>${esc(c.number)}</b> · ${esc(c.kind)}</span>`).join('')}</div>${p.shortfall?`<p class="hint">Der mangler ${p.shortfall} yderligere ledige kort.</p>`:''}${p.picked.length?'<button class="primary" data-action="replenish">Kortene er lagt i mappen</button>':''}</details>`:'<p class="hint">Mappen er fyldt til det valgte minimum.</p>'}</section>${oldestCards()}`;
}
function elapsedSince(day,today=state.today){
  if(!day)return 'Ingen dato registreret';
  let months=(Number(today.slice(0,4))-Number(day.slice(0,4)))*12+Number(today.slice(5,7))-Number(day.slice(5,7));
  const anniversary=m=>{const d=new Date(day+'T12:00:00'),n=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+m);const max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(n,max));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  if(anniversary(months)>today)months--;months=Math.max(0,months);const days=Math.max(0,dayDiff(today,anniversary(months)));
  return `${months} måned${months===1?'':'er'} og ${days} dag${days===1?'':'e'} siden`;
}
function oldestCards(){const cards=state.cards.filter(matches).sort((a,b)=>age(b)-age(a)||cmp(a.number,b.number)).slice(0,12);return `<section class="panel oldestCards"><div class="between"><h2>Længst tid siden gennemgang</h2><button data-action="go" data-page="Distrikter">Alle distriktskort</button></div><div class="tablewrap"><table><thead><tr><th>Kort / område</th><th>Senest gennemgået</th><th>Tid siden</th><th>Placering</th></tr></thead><tbody>${cards.map(c=>`<tr><td><button class="link" data-action="detail" data-id="${c.id}"><b>${esc(c.number)}</b></button><small>${esc(areaName(c.area_id))}</small></td><td>${c.last_completed?fmt(c.last_completed):'Ikke oplyst'}</td><td>${elapsedSince(c.last_completed)}${c.last_completed?`<small>${dayDiff(state.today,c.last_completed)} dage i alt</small>`:''}</td><td>${position(c)}</td></tr>`).join('')||'<tr><td colspan="4">Ingen distriktskort endnu.</td></tr>'}</tbody></table></div></section>`;}
function territories(){let ds=state.cards.filter(matches).filter(c=>status==='Alle'||status===position(c)||status==='Midlertidige'&&c.temporary).sort((a,b)=>age(b)-age(a)||cmp(a.number,b.number));return `<div class="between"><div class="toolbar"><button data-action="view" data-view="Liste" class="${view==='Liste'?'primary':''}">Liste</button><button data-action="view" data-view="Kort" class="${view==='Kort'?'primary':''}">Kort</button></div><div class="actions"><button data-admin="quick">Hurtig oprettelse</button><button class="primary" data-action="new-card">Tilføj kort</button></div></div><div class="territories"><section class="areaRail"><small>OMRÅDER</small><button data-action="area" data-id="" class="${!area?'active':''}"><span>Alle distrikter</span><b>${state.cards.length}</b></button>${state.areas.slice().sort((a,b)=>cmp(a.name,b.name)).map(a=>`<button data-action="area" data-id="${a.id}" class="${area===a.id?'active':''}"><span>${esc(a.name)}</span><b>${state.cards.filter(c=>c.area_id===a.id).length}</b></button>`).join('')}<button class="link" data-action="areas">Rediger områder</button></section><div><section class="panel">${controls(`<select id="statusFilter" aria-label="Status">${['Alle','Udleverede distriktskort','Kort i mappen','Kort i kassen','Midlertidige'].map(v=>`<option ${v===status?'selected':''}>${v}</option>`).join('')}</select>`)}<p class="hint">${ds.length} kort · ukendt / ældste gennemgang først</p>${view==='Liste'?`${AdminUI.selection()}${table(ds,true)}`:`${mapSvg(new Set(),ds)}<button data-action="go" data-page="Kortopsætning">Kortbillede og grænser</button>`}</section>${details(ds.find(c=>c.id===selected)||ds[0])}</div></div>`;}
function loans(){const q=query.toLowerCase(),active=state.loans.filter(l=>!l.returned&&(loanTab!=='Opfølgning'||fourMonths(l.cycle_start)<state.today)).filter(l=>[publisherName(l.publisher_id),card(l.card_id)?.number,areaName(card(l.card_id)?.area_id)].join(' ').toLowerCase().includes(q));const [start,end]=yearBounds();return `<div class="tabs">${['Aktive','Opfølgning','Historik'].map(t=>`<button data-action="loan-tab" data-tab="${t}" class="${loanTab===t?'active':''}">${t==='Opfølgning'?'Udleveret for længe':t}</button>`).join('')}</div><div class="toolbar"><input id="search" placeholder="Søg forkynder eller kortnummer" value="${esc(query)}"><button data-action="initial-loan">Registrer kort, der allerede er udleveret</button></div><section class="panel">${loanTab==='Forkyndere'?state.publishers.slice().sort((a,b)=>cmp(a.name,b.name)).filter(p=>p.name.toLowerCase().includes(q)).map(p=>`<div class="line"><span><b>${esc(p.name)}</b><br><small>${state.loans.filter(l=>l.publisher_id===p.id&&!l.returned).length} udleverede distriktskort</small></span><div>${state.loans.filter(l=>l.publisher_id===p.id&&!l.returned).map(l=>`<button data-action="detail" data-id="${l.card_id}">Kort ${esc(card(l.card_id)?.number)}</button>`).join(' ')} <button data-action="publisher" data-id="${p.id}">Rediger</button></div></div>`).join('')+`<button data-action="publisher">Tilføj forkynder</button>`:loanTab==='Historik'?`<div class="tablewrap"><table><thead><tr><th>Kort</th><th>Forkynder</th><th>Udleveret</th><th>Afleveret</th><th></th></tr></thead><tbody>${state.loans.filter(l=>l.assigned<=end&&(!l.returned||l.returned>=start)&&[publisherName(l.publisher_id),card(l.card_id)?.number].join(' ').toLowerCase().includes(q)).sort((a,b)=>cmp(b.assigned,a.assigned)).map(l=>`<tr><td>${esc(card(l.card_id)?.number)}</td><td>${esc(publisherName(l.publisher_id))}</td><td>${fmt(l.assigned)}</td><td>${fmt(l.returned)}</td><td><button data-admin="correct" data-id="${l.id}">Ret</button> ${l.returned?`<button class="danger" data-action="delete" data-module="loans" data-id="${l.id}">Slet</button>`:'Aktiv'}</td></tr>`).join('')}</tbody></table></div><p class="hint">Udlån, der overlapper tjenesteår ${yearLabel(year)}. Aflevering og gennemgang er separate registreringer.</p>`:`<div class="tablewrap"><table><thead><tr><th>Kort</th><th>Forkynder</th><th>Udleveret</th><th>Opfølgning fra</th><th></th></tr></thead><tbody>${active.map(l=>`<tr><td><button class="link" data-action="detail" data-id="${l.card_id}">${esc(card(l.card_id)?.number)}</button></td><td>${esc(publisherName(l.publisher_id))}</td><td>${fmt(l.assigned)}</td><td><span class="badge ${fourMonths(l.cycle_start)<state.today?'warning':''}">${fmt(fourMonths(l.cycle_start))}</span></td><td><button data-admin="correct" data-id="${l.id}">Ret</button> <button data-action="complete" data-id="${l.id}">Gennemgået</button> <button data-action="return" data-id="${l.id}">Aflever</button></td></tr>`).join('')||'<tr><td colspan="5">Ingen aktive udlån fundet.</td></tr>'}</tbody></table></div>`}<p class="hint">Opfølgning efter fire kalendermåneder i den aktuelle gennemgang. Afleverede kort går til kassen.</p></section>`;}
function publishersPage(){
  const q=query.toLowerCase(),people=state.publishers.slice().sort((a,b)=>cmp(a.name,b.name)).filter(p=>p.name.toLowerCase().includes(q));
  return `<div class="toolbar"><input id="search" placeholder="Søg forkynder" value="${esc(query)}"><button class="primary" data-action="publisher">Tilføj forkynder</button></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Forkynder</th><th>Udleverede distriktskort</th><th>Kortnumre</th><th></th></tr></thead><tbody>${people.map(p=>{const active=state.loans.filter(l=>l.publisher_id===p.id&&!l.returned).sort((a,b)=>cmp(card(a.card_id)?.number,card(b.card_id)?.number));return `<tr><td><button class="link" data-action="publisher-profile" data-id="${p.id}">${esc(p.name)}</button></td><td><span class="badge">${active.length} kort</span></td><td>${active.map(l=>`<button data-action="detail" data-id="${l.card_id}">Nr. ${esc(card(l.card_id)?.number)}</button>`).join(' ')||'—'}</td><td><button data-action="publisher-profile" data-id="${p.id}">Kort og historik</button> <button data-action="publisher" data-id="${p.id}">Rediger navn</button></td></tr>`;}).join('')||'<tr><td colspan="4">Ingen forkyndere fundet. Tilføj dem her eller ved udlevering.</td></tr>'}</tbody></table></div><p class="hint">${state.publishers.length} registrerede forkyndere · ${state.loans.filter(l=>!l.returned).length} kort udlånt i alt.</p></section>`;
}
function publisherProfile(id){
  const p=state.publishers.find(p=>p.id===id);if(!p)return;
  const active=state.loans.filter(l=>l.publisher_id===id&&!l.returned).sort((a,b)=>cmp(card(a.card_id)?.number,card(b.card_id)?.number)),history=state.loans.filter(l=>l.publisher_id===id&&l.returned).sort((a,b)=>cmp(b.assigned,a.assigned));
  openDialog(`<h2>${esc(p.name)}</h2><span class="badge">${active.length} udleverede distriktskort</span><div class="actions"><button data-action="publisher" data-id="${id}">Rediger navn</button></div><h3>Aktuelle kort</h3>${active.map(l=>`<div class="line"><span><button class="link" data-action="detail" data-id="${l.card_id}"><b>Kort ${esc(card(l.card_id)?.number)}</b></button><br><small>${esc(areaName(card(l.card_id)?.area_id))} · udleveret ${fmt(l.assigned)}</small></span><div><button data-action="complete" data-id="${l.id}">Gennemgået</button> <button data-action="return" data-id="${l.id}">Aflever</button></div></div>`).join('')||'<p class="hint">Ingen udleverede distriktskort.</p>'}<h3>Tidligere udleveringer</h3>${history.map(l=>`<div class="line"><span>Kort ${esc(card(l.card_id)?.number)}<br><small>${fmt(l.assigned)} – ${fmt(l.returned)}</small></span><button data-action="detail" data-id="${l.card_id}">Åbn kort</button></div>`).join('')||'<p class="hint">Ingen afsluttede udlån registreret.</p>'}<div class="actions"><button data-action="close">Luk</button></div>`);
}
function yearBounds(){return [`${year-1}-09-01`,`${year}-08-31`<state.today?`${year}-08-31`:state.today];}
function eventsInYear(){const [a,b]=page==='Rapporter'?Workspace.periodBounds():yearBounds();return state.completions.filter(e=>e.date>=a&&e.date<=b);}
function mapSvg(done=new Set(),cards=state.cards,draft=null,forceLegacy=false){if(!forceLegacy&&!draft&&cards.some(c=>c.geo_polygon?.length>=3))return GeoUI.reportMap(done,cards);const mapped=cards.filter(c=>c.polygon?.length>=3),missing=cards.length-mapped.length;if(!mapImage)return `<div class="mapframe">${empty('Intet lokalt kortbillede endnu. Tilføj et billede og tegn grænser under Kortopsætning. Midlertidige kort kan bruges til udlån imens.')}</div>`;return `<div class="mapframe ${editMap?'edit':''}"><svg id="localMap" viewBox="0 0 1000 700" role="img" aria-label="Distriktsgrænser på lokalt kort"><image href="${mapImage}" x="0" y="0" width="1000" height="700" preserveAspectRatio="xMidYMid meet"/>${mapped.map(c=>{const x=c.polygon.reduce((n,p)=>n+p[0],0)/c.polygon.length,y=c.polygon.reduce((n,p)=>n+p[1],0)/c.polygon.length;return `<g><polygon points="${c.polygon.map(p=>p.join(',')).join(' ')}" fill="${done.has(c.id)?'#52aa82':'#8093a4'}" fill-opacity="${done.has(c.id)?'.55':'.18'}" stroke="${done.has(c.id)?'#187149':cardColor(c)}" stroke-width="3"/><text x="${x}" y="${y}" text-anchor="middle" fill="#102a36" stroke="white" stroke-width="3" paint-order="stroke" font-size="18" font-weight="bold">${esc(c.number)}</text></g>`;}).join('')}${draft?.length?`<polyline points="${draft.map(p=>p.join(',')).join(' ')}" fill="#dfad4233" stroke="#c08b19" stroke-width="3"/>${draft.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#af7611"/>`).join('')}`:''}</svg></div><p class="hint">${missing?missing+' kort mangler en grænse og vises ikke på kortet.':''}</p>`;}
function monthlyChart(){let events=eventsInYear(),visits=state.visits.filter(v=>serviceYear(v.date)===year).sort((a,b)=>cmp(a.date,b.date)),latest=state.visits.slice().sort((a,b)=>cmp(b.date,a.date))[0],counts=Array.from({length:12},(_,i)=>{let d=new Date(year-1,8+i,1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return {key,label:d.toLocaleDateString('da-DK',{month:'short'}),n:events.filter(e=>e.date.startsWith(key)).length};}),max=Math.max(3,...counts.map(c=>c.n));return `<div class="reportchart"><h3>Gennemgange i tjenesteåret</h3><svg viewBox="0 0 760 285" role="img" aria-label="Månedlige gennemgange med gule markører for KTM-besøg">${[0,1,2,3].map(i=>`<line x1="45" y1="${225-i*50}" x2="715" y2="${225-i*50}" stroke="#e1e9ee"/><text x="33" y="${229-i*50}" text-anchor="end" font-size="10" fill="#7a8c98">${Math.round(max*i/3)}</text>`).join('')}${counts.map((c,i)=>{let h=c.n/max*150;return `<rect x="${58+i*54}" y="${225-h}" width="32" height="${Math.max(1,h)}" rx="4" fill="#5b83a3"/><text x="${74+i*54}" y="${216-h}" text-anchor="middle" font-size="11" fill="#42637c">${c.key>state.today.slice(0,7)?'—':c.n}</text><text x="${74+i*54}" y="247" text-anchor="middle" font-size="11" fill="#7a8c98">${c.label}</text>`;}).join('')}${visits.map((v,i)=>{let idx=counts.findIndex(c=>c.key===v.date.slice(0,7)),d=new Date(v.date+'T12:00:00'),days=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(),x=58+idx*54+(d.getDate()-1)/days*45,labelY=25+(i%3)*13;return `<line x1="${x}" y1="65" x2="${x}" y2="226" stroke="#d1a534" stroke-width="2" stroke-dasharray="4 3"/><path d="M${x-4} 72 L${x} 64 L${x+4} 72" stroke="#d1a534" fill="none" stroke-width="2"/><text x="${Math.min(650,Math.max(110,x))}" y="${labelY}" text-anchor="middle" fill="#946e18" font-size="10">${v.id===latest?.id?'Sidste besøg · ':''}${fmt(v.date)}</text>`;}).join('')}</svg>${visits.length?`<p class="hint">Gule pile: ${visits.map(v=>fmt(v.date)).join(' · ')}</p>`:'<p class="hint">Tilføj KTM-besøg for at vise gule pile på grafen.</p>'}</div>`;}
function allocationRows(){
  const start=`${year-1}-09-01`,end=`${year}-08-31`,rows=[];
  for(const c of [...state.cards,...(state.archived_cards||[])].sort((a,b)=>cmp(a.number,b.number))){
    const allocations=[];
    for(const l of state.loans.filter(l=>l.card_id===c.id).sort((a,b)=>cmp(a.assigned,b.assigned))){
      const finished=state.completions.filter(e=>e.loan_id===l.id).sort((a,b)=>cmp(a.date,b.date));
      let cycle=l.assigned;
      for(const e of finished){const assigned=e.assigned||cycle;if(assigned<=end&&e.date>=start)allocations.push({person:publisherName(l.publisher_id),assigned,completed:e.date<=end?e.date:null});cycle=e.date;}
      cycle=l.cycle_start||cycle;
      if((!l.returned||l.returned>=start)&&cycle<=end&&!(finished.length&&l.returned===finished[finished.length-1].date))allocations.push({person:publisherName(l.publisher_id),assigned:cycle,completed:null});
    }
    allocations.push(...state.completions.filter(e=>e.card_id===c.id&&!e.loan_id&&e.date>=start&&e.date<=end).map(e=>({person:'',assigned:null,completed:e.date})));allocations.sort((a,b)=>cmp(a.assigned||a.completed,b.assigned||b.completed));
    const previous=state.completions.filter(e=>e.card_id===c.id).flatMap(e=>[e.date,e.previous_completed]).concat(c.last_completed).filter(d=>d&&d<start).sort().pop();
    for(let i=0;i<Math.max(1,Math.ceil(allocations.length/4));i++)rows.push({number:c.number+(i?' forts.':''),previous,allocations:allocations.slice(i*4,i*4+4)});
  }
  return rows;
}
function s13Appendix(){return s13OriginalPages(allocationRows());}
function legacyReports(){const events=eventsInYear(),done=new Set(events.map(e=>e.card_id)),previous=state.completions.filter(e=>serviceYear(e.date)===year-1),[a,b]=yearBounds();return `<div class="tabs"><button data-action="report-tab" data-tab="Rapport" class="${reportTab==='Rapport'?'active':''}">Tjenesteårsrapport</button><button data-action="report-tab" data-tab="Besøg" class="${reportTab==='Besøg'?'active':''}">KTM-besøg</button><button data-action="report-tab" data-tab="Gennemgange" class="${reportTab==='Gennemgange'?'active':''}">Registrerede gennemgange</button></div>${reportTab==='Besøg'?`<section class="panel"><div class="between"><h2>KTM-besøg</h2><button class="primary" data-action="visit">Tilføj besøg</button></div>${state.visits.slice().sort((a,b)=>cmp(b.date,a.date)).map(v=>`<div class="line"><span><b>${fmt(v.date)}</b><br><small>${esc(v.note)}</small></span><div><button data-action="visit" data-id="${v.id}">Rediger</button> <button class="danger" data-action="delete" data-module="visits" data-id="${v.id}">Slet</button></div></div>`).join('')||empty('Ingen besøg registreret.')}</section>`:reportTab==='Gennemgange'?`<section class="panel"><div class="tablewrap"><table><tr><th>Dato</th><th>Kort</th><th>Område</th><th></th></tr>${events.slice().sort((a,b)=>cmp(b.date,a.date)).map(e=>`<tr><td>${fmt(e.date)}</td><td>${esc(card(e.card_id)?.number)}</td><td>${esc(areaName(card(e.card_id)?.area_id))}</td><td><button class="danger" data-action="delete" data-module="completions" data-id="${e.id}">Slet fejlregistrering</button></td></tr>`).join('')}</table></div></section>`:`<div class="toolbar"><button class="primary" data-action="print-report">Udskriv rapport / PDF</button><button data-action="s13">Hent udfyldt S-13-PDF</button><button data-action="visit">Tilføj KTM-besøg</button></div><section class="report"><div class="eyebrow">DISTRIKT · ${esc(state.settings.congregation||'MIN MENIGHED')}</div><h1>Tjenesteår ${yearLabel(year)}</h1><small>${fmt(a)} – ${fmt(b)}</small><div class="metrics"><div><small>Afsluttede gennemgange</small><strong>${events.length}</strong></div><div><small>Forskellige kort gennemgået</small><strong>${done.size} / ${state.cards.length}</strong></div><div><small>Dækning</small><strong>${state.cards.length?Math.round(done.size/state.cards.length*100):0}%</strong></div></div><p>${state.cards.length-done.size} kort er endnu ikke registreret gennemgået i tjenesteåret.</p>${monthlyChart()}<h3>Gennemgåede distrikter på kortet</h3>${ReportMap.html()}<p class="hint">Grøn: gennemgået mindst én gang i tjenesteåret. Øvrige kortfarver: endnu ikke registreret gennemgået.</p><div class="report-context">Forrige tjenesteår ${yearLabel(year-1)}: ${previous.length} registrerede gennemgange. Dette sammenligner hele de registrerede tjenesteår; indeværende år kan være uafsluttet. Kortbestand og områdegrænser er aktuelle.</div></section>${reportDetails()}${s13Appendix()}`}`;}
function reports(){return Workspace.reports();}
function addressClassification(a){const info=GeoUI.data.status?.[a.id]||{};return {owner:info.card_id?info:null,ignored:info.ignored_id||state.ignored?.find(i=>i.address_id===a.id)?.id,within:info.within||[]};}
function missingAddresses(){return GeoUI.addresses().filter(a=>!a.retired).filter(a=>{const s=addressClassification(a);return !s.owner&&!s.ignored;});}
function addressList(){
 if(['IB','Genprint'].includes(addressTab))return `<div class="tabs">${['Mangler på kort','Inden for kortgrænse','På kort','Se bort fra','IB','Genprint'].map(t=>`<button data-action="address-tab" data-tab="${t}" class="${addressTab===t?'active':''}">${t}</button>`).join('')}</div>`;
 const all=GeoUI.addresses().filter(a=>!a.retired),missing=missingAddresses(),within=missing.filter(a=>addressClassification(a).within.length),ignored=all.filter(a=>addressClassification(a).ignored),assigned=all.filter(a=>addressClassification(a).owner);
 const categories={'Mangler på kort':missing,'Inden for kortgrænse':within,'På kort':assigned,'Se bort fra':ignored};
 const q=query.toLocaleLowerCase('da'),filtered=(categories[addressTab]||missing).filter(a=>(!addressPostcode||a.postcode===addressPostcode)&&[a.road,a.number,a.postcode,a.floor,a.door,a.type].join(' ').toLocaleLowerCase('da').includes(q)).sort((a,b)=>cmp(a.road,b.road)||cmp(a.number,b.number)||cmp(a.floor,b.floor)||cmp(a.door,b.door));
 const pages=Math.max(1,Math.ceil(filtered.length/100));addressPage=Math.min(addressPage,pages-1);
 return `<div class="tabs">${Object.entries(categories).map(([name,items])=>`<button data-action="address-tab" data-tab="${name}" class="${addressTab===name?'active':''}">${name} · ${items.length}</button>`).join('')}<button data-action="address-tab" data-tab="IB" class="${addressTab==='IB'?'active':''}">IB</button><button data-action="address-tab" data-tab="Genprint" class="${addressTab==='Genprint'?'active':''}">Genprint</button></div>${['IB','Genprint'].includes(addressTab)?'':`<div class="toolbar"><input id="search" value="${esc(query)}" placeholder="Søg vej, husnummer eller adressetype"><select id="addressPostcode"><option value="">Alle postnumre</option>${[...new Set(all.map(a=>a.postcode))].sort().map(p=>`<option ${addressPostcode===p?'selected':''}>${p}</option>`).join('')}</select><button data-geo="data">Hent adresser</button></div><section class="panel"><h2>${esc(addressTab)}</h2><p class="hint">${addressTab==='Inden for kortgrænse'?'Adresser inden for en gemt distriktsgrænse, som endnu ikke er valgt til et kort.':addressTab==='Mangler på kort'?'Hentede adresser, der endnu ikke er på et distriktskort.':addressTab==='Se bort fra'?'Adresser, der springes over, fx transformerstationer.':'Adresser, der allerede er tilknyttet et distriktskort.'}</p><div class="tablewrap"><table><thead><tr><th>Adresse</th><th>Type / besøg</th><th>Kort / grænse</th><th></th></tr></thead><tbody>${filtered.slice(addressPage*100,(addressPage+1)*100).map(a=>{const s=addressClassification(a),i=state.ignored?.find(i=>i.id===s.ignored);return `<tr><td>${esc(a.road)} <b>${esc(a.number)}</b>${a.floor||a.door?'<small>'+esc([a.floor,a.door].filter(Boolean).join(' '))+'</small>':''}<small>${esc(a.postcode)}</small>${i?'<small>'+esc(i.reason)+' · '+fmt(i.date?.slice(0,10))+'</small>':''}</td><td>${esc(a.type)}<small>${a.count} besøg</small></td><td>${s.owner?s.owner.reserved?'Reserveret til kort '+esc(s.owner.card_number):`<button data-action="detail" data-id="${s.owner.card_id}">Kort ${esc(s.owner.card_number)}</button>`:s.within.map(c=>`<span class="badge">Grænse for kort ${esc(c.card_number)}</span>`).join(' ')||'—'}</td><td><div class="addressActions">${s.ignored?`<button data-action="delete" data-module="ignored" data-id="${s.ignored}">Ophæv Se bort fra</button>`:s.owner?'':`<button data-geo="assign-address" data-id="${esc(a.id)}">Tilføj til kort</button><button data-geo="ignore" data-id="${esc(a.id)}">Se bort fra</button>`}<button data-geo="type" data-id="${esc(a.id)}">Rediger type</button><button data-geo="show-address" data-id="${esc(a.id)}">Vis på kort</button></div></td></tr>`;}).join('')||'<tr><td colspan="4">Ingen adresser i denne liste.</td></tr>'}</tbody></table></div><div class="between"><small>${filtered.length} adresser · side ${addressPage+1} / ${pages}</small><div class="actions"><button data-action="address-page" data-page="${addressPage-1}" ${addressPage===0?'disabled':''}>Forrige</button><button data-action="address-page" data-page="${addressPage+1}" ${addressPage===pages-1?'disabled':''}>Næste</button></div></div></section>`}`;
}
function addressesPage(){return addressList()+(addressTab==='IB'?`<section class="panel"><div class="between"><h2>IB · kun lokalt</h2><button class="primary" data-action="ib">Tilføj IB</button></div><p class="hint">Datoen er registreringsdatoen. Ændringer kræver kun genprint af bagsiden. Antallet af besøg på forsiden ændres ikke.</p><div class="tablewrap"><table><tr><th>Kort</th><th>Vej, nr.</th><th>Registreret</th><th></th></tr>${state.ib.slice().sort((a,b)=>cmp(a.road,b.road)||cmp(a.number,b.number)).map(i=>`<tr><td>${esc(card(i.card_id)?.number)}</td><td>${esc(i.road)} ${esc(i.number)}</td><td>${fmt(i.date)}</td><td><button data-action="ib" data-id="${i.id}">Rediger</button> <button class="danger" data-action="delete" data-module="ib" data-id="${i.id}">Slet</button></td></tr>`).join('')||'<tr><td colspan="4">Ingen IB registreret.</td></tr>'}</table></div></section>`:addressTab==='Genprint'?`<section class="panel"><h2>Kort til genprint</h2><div class="actions"><button data-action="print-revisions" data-side="front" ${!state.cards.some(c=>c.front_revision)?'disabled':''}>Print ændrede forsider</button><button data-action="print-revisions" data-side="back" ${!state.cards.some(c=>c.back_revision)?'disabled':''}>Print ændrede bagsider</button></div>${state.cards.filter(c=>c.front_revision||c.back_revision).map(c=>`<div class="line"><span><b>Kort ${esc(c.number)}</b><br><small>${c.front_revision?'Forside':''}${c.front_revision&&c.back_revision?' og ':''}${c.back_revision?'bagside':''}</small></span><div><button data-action="detail" data-id="${c.id}">Se og print</button>${c.front_revision?` <button data-action="approve" data-id="${c.id}" data-side="front">Godkend forside</button>`:''}${c.back_revision?` <button data-action="approve" data-id="${c.id}" data-side="back">Godkend bagside</button>`:''}</div></div>`).join('')||empty('Ingen sider afventer genprint.')}</section>`:'');}
function legacyMapSetup(){if(!mapCard&&state.cards.length)mapCard=state.cards[0].id;return `<section class="panel"><h2>Lokalt kortbillede og distriktsgrænser</h2><p class="hint">Vælg et PNG- eller JPEG-kort fra din Mac. Billedet og de tegnede grænser lagres kun lokalt. Klik hjørnerne rundt om det valgte distrikt, og gem grænsen. Kortnumre uden grænse kan stadig bruges til udlån.</p><div class="toolbar"><label>Lokalt kortbillede <input id="mapFile" type="file" accept="image/png,image/jpeg"></label><select id="mapCard" aria-label="Kort til grænse">${state.cards.slice().sort((a,b)=>cmp(a.number,b.number)).map(c=>`<option value="${c.id}" ${mapCard===c.id?'selected':''}>Kort ${esc(c.number)} · ${esc(areaName(c.area_id))}</option>`).join('')}</select><button data-action="draw" ${!mapImage||!state.cards.length?'disabled':''}>Tegn grænse</button><button data-action="save-outline" ${!editMap||mapDraft.length<3?'disabled':''}>Gem grænse</button><button data-action="undo-point" ${!mapDraft.length?'disabled':''}>Fortryd punkt</button>${editMap?'<button data-action="cancel-outline">Annuller tegning</button>':''}</div>${mapSvg(new Set(),state.cards,editMap?mapDraft:null,true)}<p class="hint">${editMap?'Tegner kort '+esc(card(mapCard)?.number)+' · '+mapDraft.length+' punkter.':''} Udskiftning af baggrundsbilledet fjerner de gamle grænser, så de ikke vises på et forkert kort.</p></section>`;}
function settingsPage(){const cfg=state.settings;return `<div class="twocol"><section class="panel"><h2 id="settings-general">Menighed og mappe</h2><form id="settingsForm"><label>Menighedens navn</label><input name="congregation" value="${esc(cfg.congregation)}"><label style="margin-top:15px">Minimum kort i mappen</label><input name="folder_minimum" type="number" min="0" max="1000" value="${cfg.folder_minimum}" required><label style="margin-top:15px">By / land i mappen</label><select name="rural_mode"><option value="auto" ${cfg.rural_mode==='auto'?'selected':''}>Automatisk efter kortenes by/land-fordeling</option><option value="manual" ${cfg.rural_mode==='manual'?'selected':''}>Vælg minimum landkort selv</option></select><label style="margin-top:15px">Ønsket minimum landkort · ved manuel fordeling</label><input name="rural_minimum" type="number" min="0" max="${cfg.folder_minimum}" value="${cfg.rural_minimum}" required><label class="check"><input name="require_revision" type="checkbox" ${cfg.require_revision?'checked':''}> Kræv godkendt genprint før udlevering</label><p class="hint">Der er ét fysisk eksemplar af hvert kort. Alle kort i mappen er ledige. Ukendte typer kan bruges til opfyldning.</p><div class="actions"><button class="primary">Gem indstillinger</button></div></form></section><section class="panel"><h2 id="settings-areas">Områder</h2><p class="hint">Navngiv områderne efter by og land, fx Eksempelby by og Eksempelby land.</p>${state.areas.slice().sort((a,b)=>cmp(a.name,b.name)).map(a=>`<div class="line"><span>${esc(a.name)}</span><button data-action="edit-area" data-id="${a.id}">Rediger</button></div>`).join('')}<button data-action="edit-area">Tilføj område</button></section></div><section class="panel"><h2 id="settings-printing">Printprofiler</h2><p class="hint">Forside og IB-bagside huskes hver for sig. Mål og placering kan justeres i printdialogen.</p><div class="twocol">${['front','back'].map(side=>{const p=state.settings.print_profiles?.[side];return `<div><h3>${side==='front'?'Forside':'IB-bagside'}</h3><p class="hint">${p?`${p.width} × ${p.height} mm · ${p.orientation==='portrait'?'højkant':'liggende'}<br>Flyt ${p.x} mm vandret / ${p.y} mm lodret`:'Standardmål · endnu ingen gemt profil'}</p></div>`;}).join('')}</div></section><section class="panel"><h2 id="settings-data">Lokale data og historik</h2><p class="hint">Tag en lokal sikkerhedskopi, og ryd eventuelt gammel historik.</p><div class="actions"><button data-admin="storage">Pladsforbrug · kortdata</button><button data-action="open-data">Vis datamappe</button><button data-action="backup">Hent lokal sikkerhedskopi</button><button data-action="cleanup">Fjern historik ældre end 2 år</button></div>${TransferUI.html()}<p class="hint">Oprydning fjerner kun afsluttede udlån og gennemgange før skæringsdatoen. Aktive udlån og nyere data bevares. Seneste kendte gennemgang på kortet bevares.</p><p class="hint">Slettede kort, IB, besøg og historik kan gendannes i 48 timer ved fejl. Derefter fjernes de fra de aktive databasefiler. Egne sikkerhedskopier kan stadig indeholde tidligere data.</p>${state.recovery.length?`<h3>Gendan ved fejl · kun de seneste 48 timer</h3>${state.recovery.map(r=>`<div class="line"><span>${esc(r.label)}<br><small>${r.count} post${r.count!==1?'er':''} · ${new Date(r.at).toLocaleString('da-DK')}</small></span><div><button data-action="restore" data-id="${r.batch}">Gendan</button> <button class="danger" data-action="purge-recovery" data-id="${r.batch}">Slet permanent</button></div></div>`).join('')}`:''}</section>${ShareUI.html()}`;}
function render(){if(!state)return;if(typeof SetupUI!=='undefined')SetupUI.dispose();OverviewMap.dispose();ReportMap.dispose();GeoUI.dispose();el('nav').innerHTML=Navigation.html();el('congregation').textContent=(state.settings.congregation||'MIN MENIGHED').toUpperCase();const years=new Set([serviceYear(state.today),year,...state.loans.map(l=>serviceYear(l.assigned)),...state.completions.map(e=>serviceYear(e.date)),...state.visits.map(v=>serviceYear(v.date))]);el('app').innerHTML=`<div class="top"><div><h1>${Navigation.title()}</h1><p>${Workspace.subtitle(page)}</p></div>${((page==='Rapporter'&&reportTab==='Rapport')||page==='Udleverede distriktskort')?`<label>Tjenesteår <select id="serviceYear">${[...years].sort((a,b)=>b-a).map(y=>`<option value="${y}" ${y===year?'selected':''}>${yearLabel(y)}</option>`).join('')}</select></label>`:''}</div>${page==='Opstart'?SetupUI.page():page==='Forside'?Workspace.dashboard():page==='Opgaver'?Workspace.tasks():page==='Udlevering'?home():page==='Distrikter'?territories():page==='Kortoversigt'?OverviewMap.page():page==='Udleverede distriktskort'?loans():page==='Forkyndere'?publishersPage():page==='Kortnoter'?notesList():page==='Rapporter'?reports():page==='Adresser'?addressesPage():page==='Kortopsætning'?GeoUI.page():settingsPage()}<div class="foot">Distrikt ${state.version} · privat distriktsadministration</div>`;if(page==='Kortoversigt')OverviewMap.mount();if(page==='Kortopsætning')GeoUI.mount();if(page==='Rapporter'&&['Rapport','Rullende'].includes(reportTab))ReportMap.mount();if(page==='Indstillinger'&&Navigation.settingsSection==='sharing')ShareUI.load();Workspace.afterRender();if(page==='Opstart')SetupUI.mount();}
function formEnd(label='Gem'){return `<div id="formError" class="formError" role="alert"></div><div class="actions"><button class="primary">${label}</button><button type="button" data-action="close">Luk</button></div>`;}
function areaOptions(id){return `<option value="">Intet område endnu</option>${state.areas.map(a=>`<option value="${a.id}" ${id===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}`;}
function addressRow(a={road:'',numbers:'',count:1,type:'Hus'}){return `<fieldset data-address-row class="addressRow"><div class="rowhead"><b>Adresse / vejlinje</b><button type="button" data-action="remove-address">Fjern linje</button></div><div class="twocol"><div><label>Vejnavn</label><input data-field="road" value="${esc(a.road)}" required maxlength="120"></div><div><label>Numre / interval</label><input data-field="numbers" value="${esc(a.numbers)}" placeholder="1–5 (ulige) eller 1–12B" required maxlength="100"></div><div><label>Antal besøg · inkl. IB</label><input data-field="count" type="number" value="${a.count}" min="1" max="10000" required></div><div><label>Adressetype</label><select data-field="type">${addressTypes.map(t=>`<option ${t===a.type?'selected':''}>${t}</option>`).join('')}</select></div></div></fieldset>`;}
let dialogDirty=false, editGeneration=0;
function editNote(id){Workspace.noteForm(id);}
function cardColor(c){return /^#[0-9a-f]{6}$/i.test(c?.map_color||'')?c.map_color:'#477596';}
function editCard(id){const c=card(id)||{number:'',name:'',area_id:'',kind:'Ukendt',temporary:true,addresses:[]};const linked=!!(c.address_ids?.length||c.geo_addresses?.length);dialogDirty=false;editGeneration=0;openDialog(`<h2>${id?'Kort '+esc(c.number):'Tilføj kortnummer'}</h2><form id="cardForm" data-id="${id||''}"><label>Kortnummer</label><input name="number" value="${esc(c.number)}" maxlength="30" required autofocus><label class="check"><input name="temporary" type="checkbox" ${linked?'disabled':''} ${c.temporary?'checked':''}> Midlertidigt kort · kun register og udlån</label><p class="hint">Du kan tilføje vejlisten og print senere. Udlånshistorikken følger samme kort.</p><div class="twocol"><div><label>Område</label><select name="area_id">${areaOptions(c.area_id)}</select></div><div><label>Distriktstype</label><select name="kind">${['Ukendt','By','Land'].map(v=>`<option ${c.kind===v?'selected':''}>${v}</option>`).join('')}</select></div></div><label>Navn / lokal beskrivelse · valgfrit</label><input name="name" value="${esc(c.name)}" maxlength="100"><label>Farve på kortets grænse</label><input type="color" name="map_color" value="${cardColor(c)}">${!id?'<label>Seneste gennemgang · hvis kendt</label><input name="initial_completed" type="date" max="'+state.today+'">':''}<details ${!c.temporary?'open':''}><summary style="margin-top:18px">Vejliste og adressetyper</summary><fieldset ${linked?'disabled':''}><div id="addressRows">${c.addresses.map(addressRow).join('')}</div>${!linked?'<button type="button" data-action="add-address" style="margin-top:12px">Tilføj vejlinje / adresse</button>':''}</fieldset>${linked?`<p class="notice">Vejlisten følger de valgte huse. Ret adresser og besøg i korteditoren, så kort og vejliste stemmer overens.</p><button type="button" data-action="geo-card" data-id="${id}">Tegn og vælg adresser</button>`:''}<p class="hint">Hver selvstændig lejlighed og A/B-adresse tæller som ét besøg. Du angiver antal for hver linje. Sammenlagte vejlinjer bør kun bruge intervaller, der svarer til de faktiske adresser.</p></details>${id?'<div id="formSaved" class="save-indicator">Ændringer gemmes automatisk, når felterne er gyldige.</div>':''}${formEnd(id?'Gem nu':'Opret kort')}</form>`);}
function cardFormData(){const f=el('cardForm'),fd=new FormData(f);return {id:f.dataset.id||undefined,number:fd.get('number'),map_color:fd.get('map_color'),name:fd.get('name'),area_id:fd.get('area_id'),kind:fd.get('kind'),temporary:fd.has('temporary'),initial_completed:fd.get('initial_completed'),addresses:[...f.querySelectorAll('[data-address-row]')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-field]')].map(input=>[input.dataset.field,input.dataset.field==='count'?Number(input.value):input.value])))};}
async function saveCard(close){const f=el('cardForm');if(!f||!f.reportValidity())return false;const generation=editGeneration;try{await mutate('card.save',cardFormData(),{close:false,autosave:!close,message:'Kort gemt'});if(generation===editGeneration||!f.dataset.id)dialogDirty=false;if(close)await closeRequested();return true;}catch{return false;}}
function scheduleCardSave(){const f=el('cardForm');if(!f?.dataset.id)return;dialogDirty=true;editGeneration++;const note=el('formSaved');if(note)note.textContent='Venter på at gemme…';clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>{if(f.checkValidity())saveCard(false);else if(note)note.textContent='Udfyld felterne for at gemme ændringerne.';},700);}
async function closeRequested(){while(el('cardForm')?.dataset.id&&dialogDirty){if(!await saveCard(false))return;}closeDialog();}
function cardNotes(id=''){return (state.notes||[]).filter(n=>card(n.card_id)&&(!id||n.card_id===id)).sort((a,b)=>Number(a.resolved)-Number(b.resolved)||cmp(b.date,a.date)||cmp(b.created,a.created));}
function notesList(id=''){const list=cardNotes(id);return `<section class="panel"><div class="between"><h3>${id?'Kortnoter':'Noter fra indlevering og gennemgang'}</h3><button data-work="card-note" data-id="${id}">Ny opgave / note</button></div><p class="hint">Noter gemmes lokalt. En note ændrer ikke IB eller kortets besøg. Markér den som håndteret, når rettelsen er udført.</p>${list.map(n=>`<div class="line"><div>${!id?`<button class="link" data-action="detail" data-id="${n.card_id}">Kort ${esc(card(n.card_id).number)}</button> · `:''}<span class="badge ${n.resolved?'':'warning'}">${n.resolved?'Håndteret':'Afventer'}</span><small> · ${fmt(n.date)}</small><p style="white-space:pre-wrap">${esc(n.text)}</p></div><div class="actions"><button data-action="note-resolve" data-id="${n.id}">${n.resolved?'Genåbn':'Markér håndteret'}</button><button data-work="edit-note" data-id="${n.id}">Rediger</button>${!n.task?`<button data-work="make-task" data-id="${n.id}">Opret opgave</button>`:''}<button class="danger" data-action="delete" data-module="notes" data-id="${n.id}">Slet</button></div></div>`).join('')||empty('Ingen kortnoter.')}</section>`;}
function editNoteLegacy(id){const n=(state.notes||[]).find(n=>n.id===id);if(!n)return;openDialog(`<h2>Note · kort ${esc(card(n.card_id)?.number)}</h2><form id="noteForm" data-id="${n.id}"><input type="hidden" name="card_id" value="${n.card_id}"><label>Note</label><textarea name="text" maxlength="1000" required>${esc(n.text)}</textarea>${formEnd()}</form>`);}
function returnNoteField(){return '<label>Note til senere · valgfri</label><textarea name="note" maxlength="1000" placeholder="Fx tilføj IB på nr. 42"></textarea><p class="hint">Gemmes under Kortnoter og på kortets Noter-fane. Noten opretter ikke IB automatisk.</p>';}
function detail(id,tab='Kort'){
 const c=card(id);if(!c)return;selected=id;cardTab=tab;
 const histories=state.loans.filter(l=>l.card_id===id).sort((a,b)=>cmp(b.assigned,a.assigned)),l=loanFor(id),ibs=state.ib.filter(i=>i.card_id===id).sort((a,b)=>cmp(a.road,b.road)||cmp(a.number,b.number));
 const content=tab==='Kort'?`<div class="cardDisplay">${frontHTML(c)}</div>${DistrictMap.html(id)}${c.temporary?'<p class="hint">Midlertidigt kort. Nummer og udlevering er klar; vejlisten kan tilføjes senere.</p>':''}<div class="actions"><button data-action="edit-card" data-id="${id}">Rediger kort</button><button data-action="geo-card" data-id="${id}">Tegn og vælg adresser</button>${c.geo_polygon?.length>=3?`<button data-geo="export-map" data-id="${id}">Gem kortbillede · PNG</button>`:''}</div>`:tab==='Noter'?notesList(id):tab==='Adresser'?IBUI.list(id):tab==='IB-bagside'?`<p class="hint">${ibs.length} IB · gemt lokalt på din Mac</p><button data-action="ib" data-card="${id}">Tilføj IB</button>${ibs.map(i=>`<div class="line"><span>${esc(i.road)} ${esc(i.number)}<small> · ${fmt(i.date)}</small></span><div><button data-action="ib" data-id="${i.id}">Rediger</button><button class="danger" data-action="delete" data-module="ib" data-id="${i.id}">Slet</button></div></div>`).join('')||empty('Ingen IB registreret.')}<details class="backPreview"><summary>Fremvis bagsiden</summary>${backHTML(c)}</details>`:`<div class="between"><h3>Gennemgange</h3>${l?`<button data-action="complete" data-id="${l.id}">Gennemgået · behold kort</button>`:`<button data-action="record-completion" data-id="${id}">Registrer kendt gennemgang</button>`}</div>${state.completions.filter(e=>e.card_id===id).sort((a,b)=>cmp(b.date,a.date)).map(e=>`<div class="line"><span>${fmt(e.date)}</span><button class="danger" data-action="delete" data-module="completions" data-id="${e.id}">Slet</button></div>`).join('')||empty('Ingen registrerede gennemgange.')}<h3>Udleveringer</h3>${histories.map(l=>`<div class="line"><span>${esc(publisherName(l.publisher_id))}<br><small>Udleveret ${fmt(l.assigned)}</small></span><span>${l.returned?'Afleveret '+fmt(l.returned):'Aktiv'} <button data-admin="correct" data-id="${l.id}">Ret</button></span></div>`).join('')||empty('Ingen udleveringer endnu.')}`;
 openDialog(`<h2>Kort ${esc(c.number)} ${c.name?'· '+esc(c.name):''}</h2><p class="hint">${esc(areaName(c.area_id))} · ${position(c)}</p>${l&&c.back_revision?'<p class="notice warning">IB-bagsiden er ændret. Det udleverede fysiske kort skal ajourføres.</p>':''}<button data-action="show-map" data-id="${id}">Se på samlet kort</button><div class="tabs">${['Kort','Adresser','IB-bagside','Historik','Noter'].map(t=>`<button data-action="card-tab" data-id="${id}" data-tab="${t}" class="${t===tab?'active':''}">${t==='Noter'?'Noter · '+cardNotes(id).filter(n=>!n.resolved).length:t}</button>`).join('')}</div>${content}<div class="actions"><button data-action="print-options" data-id="${id}" data-side="front">Print forside</button><button data-action="print-options" data-id="${id}" data-side="back">Print IB-bagside</button><button data-action="close">Luk</button></div>${(tab==='Kort'&&c.front_revision)||(tab==='IB-bagside'&&c.back_revision)?`<p class="notice">Denne side er ændret. <button data-action="approve" data-id="${id}" data-side="${tab==='Kort'?'front':'back'}">Godkend efter print</button></p>`:''}<details class="cardMore"><summary>Flere handlinger</summary><div class="actions"><button data-work="split" data-id="${id}">Opdel kort</button><button data-work="merge" data-id="${id}">Sammenlæg kort</button>${l?`<button data-action="return" data-id="${l.id}">Aflever til kassen</button>`:`<button data-action="folder" data-id="${id}">${c.in_folder?'Flyt til kassen':'Læg i mappen'}</button>`}<button class="danger" data-action="delete" data-module="cards" data-id="${id}">Slet kort</button></div></details>`);if(tab==='Kort'){DistrictMap.mount(id);const front=el('dialog').querySelector('.cardPreview');fitFrontCard(front);if(front){frontResizeObserver?.disconnect();frontResizeObserver=new ResizeObserver(()=>fitFrontCard(front));frontResizeObserver.observe(front);}}
}
function recordCompletion(id){const c=card(id);if(!c)return;const l=loanFor(id);if(l){finish(l.id,true);return;}openDialog(`<h2>Kendt gennemgang · kort ${esc(c.number)}</h2><p class="hint">Registrér en dato, du kender. Kortets placering og udleveringshistorik ændres ikke.</p><form id="completionForm" data-id="${id}"><label>Dato for gennemgang</label><input name="date" type="date" max="${state.today}" required>${returnNoteField()}${formEnd('Gem gennemgang')}</form>`);}
function issue(id='',initial=false){const chosen=card(id);initial=initial||!!(chosen&&!chosen.in_folder);const cards=state.cards.filter(c=>!loanFor(c.id)&&(initial||c.in_folder));if(!cards.length){toast(initial?'Opret et ledigt kort først.':'Læg et ledigt kort i mappen først.');return;}id=id||cards[0].id;const c=card(id);initial=initial||!c.in_folder;openDialog(`<h2>${initial?'Registrer eksisterende udlån':'Udlever kort '+esc(c.number)}</h2><form id="issueForm"><label>Kort</label><select name="card_id">${cards.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${esc(c.number)} · ${esc(areaName(c.area_id))}</option>`).join('')}</select><label>Forkynder</label><input name="publisher_name" list="localPublisherNames" placeholder="Find en forkynder eller skriv et nyt navn" maxlength="100" required autocomplete="off"><datalist id="localPublisherNames">${state.publishers.slice().sort((a,b)=>cmp(a.name,b.name)).map(p=>`<option value="${esc(p.name)}"></option>`).join('')}</datalist><p class="hint">Et nyt navn oprettes automatisk i din lokale forkynderliste.</p><label>Udleveringsdato</label><input name="date" type="date" value="${state.today}" max="${state.today}" required><label class="check"><input name="initial" type="checkbox" ${initial?'checked':''}> Kortet var allerede udleveret før registrering</label><p class="hint">Brug dette til at skrive de nuværende udlån ind. Almindelig udlevering sker fra de ledige kort i mappen.</p>${formEnd('Registrer udlevering')}</form>`);}
function finish(id,retain){const l=state.loans.find(l=>l.id===id),c=card(l?.card_id);if(!l||!c)return;openDialog(`<h2>${retain?'Registrer gennemgang':'Aflever kort'} ${esc(c.number)}</h2><p class="hint">${esc(publisherName(l.publisher_id))}</p><form id="finishForm" data-id="${id}" data-retain="${retain?'yes':'no'}">${retain?'<p>Forkynderen beholder kortet til en ny gennemgang.</p>':'<label>Er hele distriktet gennemgået?</label><select name="complete"><option value="yes">Ja · registrer gennemgang</option><option value="no">Nej · aflever uden gennemgang</option></select>'}<label>${retain?'Gennemgangsdato':'Dato for gennemgang / aflevering'}</label><input name="date" type="date" value="${state.today}" min="${l.cycle_start}" max="${state.today}" required>${!retain?'<p class="notice">Kortet registreres tilbage i kassen derhjemme. Det bliver ikke lagt i mappen.</p>':''}${returnNoteField()}${formEnd(retain?'Gem gennemgang':'Aflever til kassen')}</form>`);}
function editPublisher(id){const p=state.publishers.find(p=>p.id===id);openDialog(`<h2>${p?'Rediger':'Tilføj'} forkynder</h2><form id="publisherForm" data-id="${id||''}"><label>Navn</label><input name="name" value="${esc(p?.name||'')}" required maxlength="100">${formEnd()}</form>`);}
function editArea(id){const a=state.areas.find(a=>a.id===id);openDialog(`<h2>${a?'Rediger':'Tilføj'} område</h2><form id="areaForm" data-id="${id||''}"><label>Områdenavn</label><input name="name" value="${esc(a?.name||'')}" required maxlength="80" placeholder="Fx Eksempelby land">${formEnd()}</form>${a?`<div class="actions"><button class="danger" data-action="delete-area" data-id="${a.id}">Slet området</button></div><p class="hint">Kortene beholdes og flyttes til “Intet område”. Området kan gendannes i 48 timer.</p>`:''}`);}
function editVisit(id){const v=state.visits.find(v=>v.id===id);openDialog(`<h2>KTM-besøg</h2><form id="visitForm" data-id="${id||''}"><label>Besøgsdato</label><input name="date" type="date" value="${v?.date||state.today}" max="${state.today}" required><label>Note · valgfri</label><input name="note" value="${esc(v?.note||'')}" maxlength="200">${formEnd()}</form>`);}
function editIB(id,cardId){IBUI.open(id,cardId,'',!!cardId);}
function confirmDelete(module,id){const item=state[module]?.find(i=>i.id===id);if(!item)return;openDialog(`<h2>Slet ${module==='cards'?'kort '+esc(item.number):module==='ib'?'IB-adressen':module==='visits'?'KTM-besøget':'registreringen'}?</h2><p>${module==='cards'?'Kortet og dets udlån, gennemgange og IB fjernes fra visningen.':'Registreringen fjernes fra visningen.'}</p><p class="hint">Du kan gendanne ved fejl under Indstillinger i 48 timer. Derefter fjernes data fra databasefilerne. Egne sikkerhedskopier kan stadig indeholde posten.</p><div class="actions"><button class="danger" data-action="confirm-delete" data-module="${module}" data-id="${id}">Slet</button><button data-action="close">Annuller</button></div>`);}
function compactAddressNumbers(value){const raw=String(value??'').trim(),parts=raw.split(/[,;]+/).map(s=>s.trim());if(parts.length>1&&parts.every(s=>/^\d+\s*[A-Za-zÆØÅæøå]*$/.test(s))){parts.sort((a,b)=>cmp(a,b));return parts[0]+'-'+parts[parts.length-1];}return raw.replace(/[–—]/g,'-');}
function frontHTML(c){const shared=(state.public_maps||[]).some(p=>p.card_id===c.id);return `<div class="cardPreview"><img src="${location.origin}/s12-template.png" alt="S-12-skabelon"><div class="title">${esc(c.name||(c.area_id?areaName(c.area_id):''))}</div><div class="number">${esc(c.number)}</div><div class="streets">${c.addresses.map(a=>`<div><span>${esc(a.road)} ${esc(compactAddressNumbers(a.numbers))}</span><span>${a.count} besøg</span></div>`).join('')}${c.temporary?'':`<div><b>I alt</b><b>${visitsCount(c)} besøg</b></div>`}</div>${shared?`<div class="cardQR"><span>Scan for at se et kort over distriktet</span><img data-card-qr src="${location.origin}/card-qr.svg?card_id=${encodeURIComponent(c.id)}" alt="QR-kode til kort over distriktet"></div>`:''}</div>`;}
function backHTML(c){const items=state.ib.filter(i=>i.card_id===c.id).sort((a,b)=>cmp(a.road,b.road)||cmp(a.number,b.number)),roads=[...new Set(items.map(i=>i.road))];return `<div class="ibPreview"><div class="ibHead"><b>Kort nr. ${esc(c.number)}</b><b>ØNSKER IKKE BESØG</b></div><div class="ibCols"><b>Vejnavn, nr.</b><b>Dato</b></div>${roads.map(r=>`<section><h4>${esc(r)}</h4>${items.filter(i=>i.road===r).map(i=>`<div class="ibRow"><span>${esc(i.number)}</span><span>${fmt(i.date)}</span></div>`).join('')}</section>`).join('')}</div>`;}
async function download(path,name){const r=await api(path),blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;addressPage=0;const p=e.target.selectionStart;render();el('search')?.focus();el('search')?.setSelectionRange(p,p);}else if(e.target.closest('#cardForm'))scheduleCardSave();});
document.addEventListener('change',async e=>{try{if(e.target.id==='serviceYear'){year=Number(e.target.value);render();}else if(e.target.id==='addressPostcode'){addressPostcode=e.target.value;addressPage=0;render();}else if(e.target.id==='areaFilter'){area=e.target.value;render();}else if(e.target.id==='statusFilter'){status=e.target.value;render();}else if(e.target.id==='mapCard'){mapCard=e.target.value;mapDraft=[];editMap=false;render();}else if(e.target.id==='printOrientation'){let f=e.target.form,w=f.elements.width,h=f.elements.height,a=Number(w.value),b=Number(h.value);w.value=e.target.value==='portrait'?Math.min(a,b):Math.max(a,b);h.value=e.target.value==='portrait'?Math.max(a,b):Math.min(a,b);}else if(e.target.id==='mapFile'){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Billedet må højst være 5 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});openDialog(`<h2>Brug det nye kortbillede?</h2><p>Billedet lagres kun lokalt. Gamle tegnede grænser fjernes, fordi de ikke nødvendigvis passer til det nye billede.</p><div class="actions"><button id="confirmMap" class="primary">Brug billedet</button><button data-action="close">Annuller</button></div>`);el('confirmMap').addEventListener('click',async()=>{try{await mutate('map.save',{image:data,name:file.name});await loadMap();render();}catch{}});}else if(e.target.closest('#cardForm'))scheduleCardSave();}catch(e){toast(e.message);}});
async function loadMap(){const m=await(await api('/api/map')).json();mapImage=m.image||'';}
document.addEventListener('click',async event=>{const map=event.target.closest('#localMap');if(map&&editMap){const pt=map.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;const p=pt.matrixTransform(map.getScreenCTM().inverse());mapDraft.push([Math.max(0,Math.min(1000,p.x)),Math.max(0,Math.min(700,p.y))]);render();return;}const target=event.target.closest('[data-action]');if(!target)return;event.preventDefault();const d=target.dataset;try{switch(d.action){
case 'go':if(d.page==='Adresser'){if(!GeoUI.loaded)await GeoUI.load();addressPage=0;}if(page==='Kortopsætning'&&d.page!==page&&!GeoUI.canLeave())return;if(d.page!==page){if(GeoUI.whole)GeoUI.polygon=(GeoUI.data.main_boundary?.points||[]).map(p=>p.slice());GeoUI.dirty=false;}await closeRequested();if(el('dialog').open)return;page=d.page;query='';area='';render();break;
case 'close':await closeRequested();break;
case 'geo-card':await closeRequested();if(el('dialog').open)return;GeoUI.openCard(d.id);break;
case 'address-tab':addressTab=d.tab;addressPage=0;query='';render();break;
case 'address-page':addressPage=Number(d.page);render();break;
case 'publisher-profile':publisherProfile(d.id);break;
case 'new-card':editCard();break;
case 'edit-card':editCard(d.id);break;
case 'select':selected=d.id;render();break;
case 'detail':detail(d.id);break;
case 'show-map':await OverviewMap.open(d.id);break;
case 'card-tab':detail(d.id,d.tab);break;
case 'note-edit':editNote(d.id);break;
case 'note-resolve':{const n=(state.notes||[]).find(n=>n.id===d.id);if(n){await mutate('note.resolve',{id:n.id,resolved:!n.resolved});detail(n.card_id,'Noter');}break;}
case 'record-completion':recordCompletion(d.id);break;
case 'desk-tab':deskTab=d.tab;query='';render();break;
case 'stock':query='';area='';if(d.status==='Udleverede distriktskort'){page=d.status;loanTab='Aktive';}else{page='Distrikter';status=d.status;}render();break;
case 'print-revisions':printRevisions(d.side);break;
case 'print-defaults':{const f=el('printForm');printOptions(f.dataset.id,f.dataset.side,JSON.parse(f.dataset.ids),true);break;}
case 'issue':issue(d.id);break;
case 'initial-loan':issue('',true);break;
case 'return':finish(d.id,false);break;
case 'complete':finish(d.id,true);break;
case 'folder':await mutate('folder.set',{ids:[d.id],in_folder:!card(d.id).in_folder},{close:false,message:'Kortets placering gemt'});break;
case 'replenish':await mutate('folder.set',{ids:folderPlan().picked.map(c=>c.id),in_folder:true},{close:false,message:'Kortene er registreret i mappen'});break;
case 'view':if(d.view==='Kort'){await OverviewMap.open('',status,area,query);}else{view=d.view;render();}break;
case 'area':area=d.id;render();break;
case 'areas':page='Indstillinger';render();break;
case 'edit-area':editArea(d.id);break;
case 'delete-area':openDialog(`<h2>Slet området?</h2><p>Kortene beholdes under “Intet område”. Gendannelse ved fejl er mulig i 48 timer.</p><div class="actions"><button class="danger" data-action="confirm-area-delete" data-id="${d.id}">Slet området</button><button data-action="close">Annuller</button></div>`);break;
case 'confirm-area-delete':await mutate('area.delete',{id:d.id},{message:'Området slettet; kortene er bevaret'});area='';break;
case 'loan-tab':loanTab=d.tab;query='';render();break;
case 'publisher':editPublisher(d.id);break;
case 'report-tab':reportTab=d.tab;render();break;
case 'visit':editVisit(d.id);break;
case 'ib':editIB(d.id,d.card);break;
case 'delete':confirmDelete(d.module,d.id);break;
case 'confirm-delete':await mutate('delete',{module:d.module,id:d.id},{message:'Slettet · kan gendannes i 48 timer ved fejl'});break;
case 'purge-recovery':if(window.confirm('Slet hele denne gendannelsespost permanent? Den kan derefter ikke gendannes fra appen.'))await mutate('recovery.purge',{batch:d.id},{close:false,message:'Posten er slettet permanent'});break;
case 'restore':await mutate('restore',{batch:d.id},{close:false,message:'Gendannet'});break;
case 'approve':openDialog(`<h2>Godkend ${d.side==='front'?'forside':'bagside'}?</h2><p>Bekræft, at siden er kontrolleret og printet til det fysiske kort.</p><div class="actions"><button class="primary" data-action="confirm-approve" data-id="${d.id}" data-side="${d.side}">Kontrolleret og printet</button><button data-action="close">Annuller</button></div>`);break;
case 'confirm-approve':await mutate('revision.approve',{card_id:d.id,side:d.side},{message:'Siden er godkendt'});break;
case 'draw':editMap=true;mapDraft=[];render();break;
case 'undo-point':mapDraft.pop();render();break;
case 'cancel-outline':editMap=false;mapDraft=[];render();break;
case 'save-outline':await mutate('map.outline',{card_id:mapCard,points:mapDraft},{close:false,message:'Distriktsgrænsen er gemt'});editMap=false;mapDraft=[];render();break;
case 'print-report':await printReport();break;
case 's13':await download('/api/export/s13?year='+year,'S-13-'+yearLabel(year).replace('/','-')+'.pdf');break;
case 'print-options':printOptions(d.id,d.side);break;
case 'open-data':{const r=await(await api('/api/open-data',{})).json();toast('Datamappe på serveren: '+r.path);} break;
case 'logout':await api('/api/logout',{});location.replace('/');break;
case 'backup':await download('/api/export/backup','Distrikt-sikkerhedskopi-'+state.today+'.zip');await mutate('backup.record',{}, {close:false,message:'Privat sikkerhedskopi hentet'});break;
case 'cleanup':{const info=await(await api('/api/data-info')).json(),count=state.loans.filter(l=>l.returned&&l.returned<info.cutoff).length+state.completions.filter(e=>e.date<info.cutoff).length;openDialog(`<h2>Ryd historik før ${fmt(info.cutoff)}?</h2><p>${count} afsluttede udlån / gennemgange fjernes. Aktive udlån, nyere registreringer, IB, forkyndere og KTM-besøg beholdes.</p><p class="hint">Seneste kendte gennemgang på kortet bevares. Gendannelse ved fejl er mulig i 48 timer.</p><div class="actions"><button class="danger" data-action="confirm-cleanup">Fjern den gamle historik</button><button data-action="close">Annuller</button></div>`);break;}
case 'confirm-cleanup':await mutate('history.cleanup',{},{message:'Gammel historik fjernet · 48 timers gendannelse ved fejl'});break;
case 'add-address':el('addressRows').insertAdjacentHTML('beforeend',addressRow());scheduleCardSave();break;
case 'remove-address':target.closest('[data-address-row]').remove();scheduleCardSave();break;
case 'stop':openDialog('<h2>Luk den lokale app?</h2><p>Alle gemte registreringer beholdes. Startfilen åbner appen igen.</p><div class="actions"><button data-action="confirm-stop">Luk appen</button><button data-action="close">Annuller</button></div>');break;
case 'confirm-stop':await saveQueue;await api('/api/shutdown',{});el('app').innerHTML='<section class="panel"><h1>Distrikt er lukket</h1><p>Dine data er gemt. Åbn Start-Distrikt.command for at starte igen.</p></section>';closeDialog();saved('Lukket · data er gemt');break;
}}catch(e){toast(e.message);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id||(form.id.startsWith('geo')||form.id.startsWith('admin')))return;e.preventDefault();if(form.dataset.saving==='yes'||!form.reportValidity())return;form.dataset.saving='yes';const submitButton=form.querySelector('button:not([type=button])');if(submitButton)submitButton.disabled=true;const fd=new FormData(form),fields=Object.fromEntries(fd);try{switch(form.id){
case 'cardForm':clearTimeout(autosaveTimer);await saveCard(true);break;
case 'issueForm':await mutate('loan.issue',{card_id:fields.card_id,publisher_name:fields.publisher_name,date:fields.date,initial:fd.has('initial')},{message:'Udlevering gemt'});break;
case 'finishForm':await mutate('loan.finish',{id:form.dataset.id,date:fields.date,complete:form.dataset.retain==='yes'||fields.complete==='yes',retain:form.dataset.retain==='yes',note:fields.note},{message:form.dataset.retain==='yes'?'Gennemgang gemt; kortet beholdes':'Afleveret til kassen'});break;
case 'publisherForm':await mutate('publisher.save',{id:form.dataset.id||undefined,name:fields.name});break;
case 'areaForm':await mutate('area.save',{id:form.dataset.id||undefined,name:fields.name});break;
case 'noteForm':await mutate('note.save',{id:form.dataset.id,...fields});break;
case 'visitForm':await mutate('visit.save',{id:form.dataset.id||undefined,date:fields.date,note:fields.note});break;
case 'ibForm':{const returnToCard=form.dataset.returnCard==='yes';await mutate('ib.save',{id:form.dataset.id||undefined,...fields},{message:'IB gemt · kun bagsiden skal genprintes'});if(returnToCard)detail(fields.card_id,'Adresser');break;}
case 'settingsForm':await mutate('settings.save',{...fields,folder_minimum:Number(fields.folder_minimum),rural_minimum:Number(fields.rural_minimum),require_revision:fd.has('require_revision')},{close:false,message:'Indstillinger gemt'});break;
case 'printForm':await printCard(form);break;
case 'completionForm':await mutate('completion.record',{card_id:form.dataset.id,date:fields.date,note:fields.note},{message:'Gennemgang gemt'});break;
}}catch(e){const err=el('formError');if(err)err.textContent=e.message;failed(e.message);}finally{delete form.dataset.saving;if(submitButton)submitButton.disabled=false;}});
el('dialog').addEventListener('cancel',e=>{e.preventDefault();closeRequested();});
window.addEventListener('beforeunload',e=>{if(dialogDirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{await refresh();year=serviceYear(state.today);await GeoUI.resumeJob();render();saved();Workspace.boot();}catch(e){failed(e.message);el('app').innerHTML=`<section class="panel"><h1>Den lokale app kunne ikke åbnes</h1><p>${esc(e.message)}</p><p>Start den fra Start-Distrikt.command igen.</p></section>`;}})();
